import {profile,projects,certificates} from './content.js';
const $=s=>document.querySelector(s);let soundOn=false,audio,filmPlaying=false,lastSound=0;
try{soundOn=localStorage.getItem('sadman-sound')==='on'}catch{}
const soundButton=$('#sound');function updateSound(){soundButton.setAttribute('aria-pressed',String(soundOn));soundButton.setAttribute('aria-label',soundOn?'Mute interface sound':'Enable interface sound');soundButton.textContent=soundOn?'Sound on ◉':'Sound off ◌'}updateSound();
async function unlock(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')await audio.resume()}catch{soundOn=false;updateSound()}}
function tone(kind='tap'){if(!soundOn||filmPlaying||!audio||audio.state!=='running')return;const now=audio.currentTime;if(now-lastSound<.07)return;lastSound=now;const notes=kind==='open'?[440,660]:kind==='close'?[360]:kind==='intro'?[330,440,660]:kind==='success'?[520,780]:[560];notes.forEach((freq,i)=>{const osc=audio.createOscillator(),gain=audio.createGain(),t=now+i*.065;osc.type='sine';osc.frequency.setValueAtTime(freq,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.035,t+.008);gain.gain.exponentialRampToValueAtTime(.0001,t+.19);osc.connect(gain);gain.connect(audio.destination);osc.start(t);osc.stop(t+.2)})}
soundButton.addEventListener('click',async()=>{soundOn=!soundOn;if(soundOn)await unlock();updateSound();try{localStorage.setItem('sadman-sound',soundOn?'on':'off')}catch{}if(soundOn)tone('intro');toast(soundOn?'Interface sound enabled':'Interface sound muted')});
document.addEventListener('pointerdown',()=>{if(soundOn)void unlock()},{once:true});document.addEventListener('keydown',()=>{if(soundOn)void unlock()},{once:true});document.addEventListener('click',e=>{if(e.target.closest('a,button')&&!e.target.closest('#sound'))tone('tap')});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
const menu=$('#menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('nav').classList.toggle('open',open)});$('nav').addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');$('nav').classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}});
$('#projects').innerHTML=projects.map((p,i)=>`<article class="project"><div class="project-visual ${p.class}"><span class="project-wordmark">${p.title}${i===0?'<span style="color:#c9b3ff">.</span>':''}</span><div class="project-headline">${p.headline}</div><span class="visual-note">${p.kind.toUpperCase()} / ${p.year}</span></div><div class="project-body"><span class="project-meta">${p.number} / ${p.kind.toUpperCase()}</span><h3>${p.title}</h3><p>${p.description}</p><button class="project-button" data-project="${i}">Explore project <span>↗</span></button></div></article>`).join('');
const dialog=$('#detail'),dialogContent=$('#dialog-content');let returnFocus;function showDialog(label){returnFocus=document.activeElement;$('#dialog-label').textContent=label;dialog.showModal();document.body.classList.add('no-scroll');tone('open');$('#close-dialog').focus()}function closeDialog(){dialog.close()}$('#close-dialog').onclick=closeDialog;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});dialog.addEventListener('close',()=>{document.body.classList.remove('no-scroll');returnFocus?.focus();tone('close')});
$('#projects').addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;const p=projects[Number(b.dataset.project)];dialogContent.innerHTML=`<article class="project-detail"><p class="eyebrow">${p.kind} / ${p.year} / ${p.role}</p><h2 id="modal-title">${p.title}</h2><p>${p.description}</p>${p.url?`<a class="button primary" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.link}</a>`:''}</article>`;dialog.setAttribute('aria-labelledby','modal-title');showDialog('SELECTED WORK / '+p.number)});
let category='All',query='';$('#certificate-total').textContent=certificates.length;const categories=['All',...new Set(certificates.map(c=>c.category))];$('#filters').innerHTML=categories.map(c=>`<button data-category="${c}" aria-pressed="${c==='All'}">${c}${c==='All'?' / '+certificates.length:''}</button>`).join('');function renderCertificates(){const shown=certificates.filter(c=>(category==='All'||c.category===category)&&`${c.title} ${c.issuer} ${c.date} ${c.detail}`.toLowerCase().includes(query));$('#results-status').textContent=`Showing ${shown.length} of ${certificates.length} credentials`;$('#certificate-grid').innerHTML=shown.length?shown.map(c=>`<button class="certificate-card" data-certificate="${c.id}" aria-label="View ${c.title} certificate"><div class="certificate-image"><img src="assets/${c.id}.webp" width="600" height="440" loading="lazy" alt="Authentic ${c.title} certificate issued to Sadman Labib Chowdhury"><span class="expand" aria-hidden="true">↗</span></div><div class="certificate-category"><span>${c.category}</span><span>${c.year}</span></div><h3>${c.title}</h3><p>${c.issuer}</p></button>`).join(''):'<p class="empty">No credentials match your search. Try another term or category.</p>'}renderCertificates();$('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$('#filters').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderCertificates()});$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();renderCertificates()});
$('#certificate-grid').addEventListener('click',e=>{const b=e.target.closest('[data-certificate]');if(!b)return;const c=certificates.find(c=>c.id===b.dataset.certificate);dialogContent.innerHTML=`<div class="viewer-tools"><button id="zoom-out" aria-label="Zoom certificate out">−</button><button id="zoom-in" aria-label="Zoom certificate in">+</button><button id="zoom-reset">Fit</button><span id="zoom-level" aria-live="polite">100%</span><a href="assets/${c.original}" target="_blank" rel="noopener noreferrer">Open original ↗</a></div><div class="image-viewer" tabindex="0" aria-label="Certificate image; use zoom controls or browser pinch zoom"><img id="full-certificate" src="assets/${c.id}.webp" alt="${c.title} certificate for Sadman Labib Chowdhury"></div><div class="certificate-details"><h2 id="modal-title">${c.title}</h2><p>${c.issuer} · ${c.date}</p><p>${c.detail}</p>${c.id==='saylor'?'<p>6 hours · 0.6 CEUs · Grade 84.44%</p>':''}</div>`;let zoom=100;const apply=()=>{$('#full-certificate').style.width=zoom+'%';$('#zoom-level').textContent=zoom+'%'};$('#zoom-in').onclick=()=>{zoom=Math.min(300,zoom+25);apply()};$('#zoom-out').onclick=()=>{zoom=Math.max(100,zoom-25);apply()};$('#zoom-reset').onclick=()=>{zoom=100;apply()};dialog.setAttribute('aria-labelledby','modal-title');showDialog('CREDENTIAL / '+c.category.toUpperCase())});
const video=$('#intro-video');video.addEventListener('play',()=>{filmPlaying=true});for(const event of ['pause','ended'])video.addEventListener(event,()=>{filmPlaying=false});
$('#copy-email').onclick=async()=>{try{await navigator.clipboard.writeText(profile.email);toast('Email address copied');tone('success')}catch{toast('Copy unavailable. Use the email link to get in touch.')}};
let scheduled=false;function progress(){const max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(max>0?scrollY/max*100:0)+'%';scheduled=false}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(progress)}},{passive:true});progress();
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-top,.intro h2,.intro-aside,.project,.article,.timeline,.contact h2').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
